-- Reference data: hangman word bank, game missions and the challenges section (generated).
-- Idempotent: rows that already exist are kept as they are.

UPDATE public.universe_settings st SET features = st.features || '["challenges"]'::jsonb
  FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'harry-potter' AND NOT st.features ? 'challenges';
UPDATE public.universe_settings st SET features = st.features || '["challenges"]'::jsonb
  FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'greys-anatomy' AND NOT st.features ? 'challenges';
UPDATE public.universe_settings st SET features = st.features || '["challenges"]'::jsonb
  FROM public.universes u WHERE u.id = st.universe_id AND u.slug = 'bts' AND NOT st.features ? 'challenges';


